    const POS_STORAGE_KEY = 'crm-metro-station-pos-v3';
    const SIZE_KEY = 'crm-metro-pin-size';
    function applyPinSize(px) {
        document.documentElement.style.setProperty('--mm-pin-size', px + 'px');
    }
    function loadPositions() {
        try {
            const saved = JSON.parse(localStorage.getItem(POS_STORAGE_KEY) || '{}');
            return Object.assign({}, DEFAULT_POS, saved);
        } catch(e) { return Object.assign({}, DEFAULT_POS); }
    }
    function savePositions(pos) {
        try { localStorage.setItem(POS_STORAGE_KEY, JSON.stringify(pos)); } catch(e) {}
    }
    let STATION_POS = loadPositions();

    /* =========================================================
     *  4. ВРЕМЕННЫЕ СЛОТЫ
     * ========================================================= */
    const TIME_SLOTS = (() => {
        const out = [];
        // Работаем с 09:00 до 21:00 — последний слот 20:30 = 20:30–21:00.
        for (let h = 9; h <= 20; h++) {
            out.push(`${String(h).padStart(2,'0')}:00`);
            out.push(`${String(h).padStart(2,'0')}:30`);
        }
        return out;
    })();

    /* =========================================================
     *  5. ПАРСИНГ — ПОЗИЦИОННЫЙ.
     *     Колонка → address_id из соответствующего <th>.
     *     Строка <tr data-time="H"> + смещение (0=00, 1=30) → время.
     *     В ячейке смотрим что есть:
     *       • record/edit → запись
     *       • record/create → свободно
     *       • ничего → закрыто
     * ========================================================= */
    function parseTable() {
        const table = document.getElementById('r-stat-table');
        if (!table) return null;

        const addresses = {};
        const colToAid = {}; // index колонки → address_id
        const headers = table.querySelectorAll('th[id^="address_id_"]');
        headers.forEach((th, idx) => {
            const m = th.id.match(/address_id_(\d+)/);
            if (!m) return;
            const id = m[1];
            const title = th.textContent.trim();
            const meta = findMeta(title);
            addresses[id] = {
                id, title,
                short:   meta ? meta.short : title.split(',').pop().trim(),
                station: meta ? meta.station : null,
                line:    meta ? meta.line : null,
                box:     meta ? meta.box : '',
                layout:  meta ? meta.layout : '',
                height:  meta ? meta.height : '',
                note:    meta && meta.note ? meta.note : '',
                slots:   {},
            };
            // в исходнике первая колонка — время, потом по одной на th
            // index + 1 — позиция td в строке
            colToAid[idx + 1] = id;
        });

        const allTimes = new Set(TIME_SLOTS);

        // Идём по парам строк часа
        const hourRows = table.querySelectorAll('tr[data-time]');
        hourRows.forEach((row1) => {
            const h = parseInt(row1.getAttribute('data-time'), 10);
            const row2 = row1.nextElementSibling;
            if (!row2 || row2.tagName !== 'TR') return;

            const rows = [
                { row: row1, time: `${String(h).padStart(2,'0')}:00` },
                { row: row2, time: `${String(h).padStart(2,'0')}:30` },
            ];

            rows.forEach(({row, time}) => {
                if (!allTimes.has(time)) return;
                // первая ячейка — пустая или с временем-меткой; пропускаем её,
                // дальше td.time-cell идут в позиционном порядке.
                const cells = row.querySelectorAll('td');
                let colIdx = 0;
                cells.forEach((td) => {
                    if (!td.classList.contains('time-cell')) return;
                    colIdx++;
                    const aid = colToAid[colIdx];
                    if (!aid) return;

                    const items = []; // все записи + все «Добавить» из этой ячейки

                    // Каждый блок r-stat-head — отдельная запись
                    td.querySelectorAll('[class*="address_id_"].r-stat-head').forEach((block) => {
                        const editA = block.querySelector('a[href*="/admin/record/edit"]');
                        if (!editA) return;
                        const delA  = block.querySelector('a[href*="/admin/record/delete"]');
                        const lines = block.textContent.split('\n').map(s=>s.trim()).filter(Boolean);
                        const customer = lines[lines.length - 1] || '';
                        // Статус — ищем svg в блоке-маркере, который идёт перед текущим r-stat-head.
                        // Безопаснее посмотреть в самой ячейке: если есть несколько маркеров,
                        // используем тот, что предшествует данному блоку.
                        let status = '';
                        let prev = block.previousElementSibling;
                        // Маркер выше: <div class="checked|too-late|is-new"><svg class="..."/></div>
                        // Идём вверх до 4 шагов
                        for (let k = 0; k < 4 && prev; k++, prev = prev.previousElementSibling) {
                            if (prev.querySelector && prev.querySelector('svg.checked'))      { status = 'checked'; break; }
                            if (prev.querySelector && prev.querySelector('svg.too-late'))     { status = 'late';    break; }
                            if (prev.querySelector && prev.querySelector('svg.is-new'))       { status = 'new';     break; }
                        }
                        // Запасной вариант — взять первый встречный маркер в td
                        if (!status) {
                            if (td.querySelector('svg.checked'))      status = 'checked';
                            else if (td.querySelector('svg.too-late')) status = 'late';
                            else if (td.querySelector('svg.is-new'))   status = 'new';
                        }
                        items.push({
                            kind: 'booked',
                            time, customer,
                            editUrl: editA.getAttribute('href'),
                            deleteUrl: delA ? delA.getAttribute('href') : '',
                            status,
                        });
                    });

                    // Каждое «Добавить» — отдельный пустой слот (= свободный бокс)
                    td.querySelectorAll('a[href*="/admin/record/create"]').forEach((createA) => {
                        items.push({
                            kind: 'empty',
                            time,
                            createUrl: createA.getAttribute('href'),
                        });
                    });

                    if (items.length) {
                        addresses[aid].slots[time] = items;
                    }
                    // иначе — закрыто, ничего не пишем
                });
            });
        });

        return addresses;
    }

    function findMeta(title) {
        const t = title.toLowerCase();
        for (const m of ADDRESS_META) {
            if (t.indexOf(m.match.toLowerCase()) !== -1) return m;
        }
        return null;
    }

